window.__COMPONENT_CACHE__["reports/tg20-report.html"] = "<!DOCTYPE html>\r\n<html lang=\"tr\">\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <title data-i18n=\"reports.tg20MainTitle\"></title>\r\n  <link rel=\"stylesheet\" href=\"../css/layout.css\">\r\n</head>\r\n<body class=\"report-body\">\r\n  <button class=\"print-float-action\" onclick=\"window.print()\" data-i18n=\"reports.btnPrint\"></button>\r\n\r\n  <div class=\"report-container\">\r\n    <div class=\"report-header-banner\">\r\n      <div>\r\n        <div class=\"brand-title\" data-i18n=\"reports.tg20BrandTitle\"></div>\r\n        <div class=\"brand-sub\" data-i18n=\"reports.tg20BrandSub\"></div>\r\n      </div>\r\n      <div class=\"report-meta-header\">\r\n        <div><strong data-i18n=\"reports.tg20MetaHeader\"></strong></div>\r\n        <div><span data-i18n=\"reports.lblDateTime\"></span> <strong>{{DATE}} {{TIME}}</strong></div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"report-title-banner\">\r\n      <h1 data-i18n=\"reports.tg20MainTitle\"></h1>\r\n      <p data-i18n=\"reports.tg20SubTitle\"></p>\r\n    </div>\r\n\r\n    <div class=\"meta-grid\">\r\n      <div class=\"meta-item\"><span class=\"meta-label\" data-i18n=\"reports.lblProject\"></span><span class=\"meta-value\">{{PROJECT}}</span></div>\r\n      <div class=\"meta-item\"><span class=\"meta-label\" data-i18n=\"reports.lblCalcDate\"></span><span class=\"meta-value\">{{DATE}} - {{TIME}}</span></div>\r\n      <div class=\"meta-item\"><span class=\"meta-label\" data-i18n=\"reports.lblProjection\"></span><span class=\"meta-value\">{{PROJECTION_STR}}</span></div>\r\n      <div class=\"meta-item\"><span class=\"meta-label\" data-i18n=\"reports.lblGeoidModel\"></span><span class=\"meta-value\" data-i18n=\"reports.valGeoidModel\"></span></div>\r\n      <div class=\"meta-item\"><span class=\"meta-label\" data-i18n=\"reports.lblTotalPoints\"></span><span class=\"meta-value\">{{TOTAL_POINTS}}</span></div>\r\n      <div class=\"meta-item\"><span class=\"meta-label\" data-i18n=\"reports.lblVerticalDatum\"></span><span class=\"meta-value\" data-i18n=\"reports.valVerticalDatum\"></span></div>\r\n    </div>\r\n\r\n    <div class=\"report-formula-bar\">\r\n      <div class=\"formula-math\"><strong data-i18n=\"reports.formulaTitle\"></strong>&nbsp;&nbsp; <span>H<sub>ortometrik</sub> = h<sub>elipsoit</sub> − N<sub>TG-20</sub></span></div>\r\n      <div class=\"formula-stats\"><span data-i18n=\"reports.avgUndulationPrefix\"></span> <strong>{{AVG_UNDULATION}}</strong></div>\r\n    </div>\r\n\r\n    <table class=\"report-table\">\r\n      <thead>\r\n        <tr>\r\n          <th class=\"col-num\" data-i18n=\"reports.thNum\"></th>\r\n          <th class=\"col-pname\" data-i18n=\"reports.thPointName\"></th>\r\n          <th class=\"col-lat\" data-i18n=\"reports.thLat\"></th>\r\n          <th class=\"col-lon\" data-i18n=\"reports.thLon\"></th>\r\n          <th class=\"col-metric\" data-i18n=\"reports.thEastM\"></th>\r\n          <th class=\"col-metric\" data-i18n=\"reports.thNorthM\"></th>\r\n          <th class=\"col-metric\" data-i18n=\"reports.thElevEllipsoidM\"></th>\r\n          <th class=\"col-metric col-geoid\" data-i18n=\"reports.thUndulationM\"></th>\r\n          <th class=\"col-metric col-ortho\" data-i18n=\"reports.thElevOrthoM\"></th>\r\n          <th class=\"col-obstype\" data-i18n=\"reports.thObsType\"></th>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n        {{TABLE_ROWS}}\r\n      </tbody>\r\n    </table>\r\n\r\n    <div class=\"report-disclaimer\">\r\n      <div class=\"disclaimer-title\" data-i18n=\"reports.disclaimerTitle\"></div>\r\n      <div data-i18n=\"reports.disclaimerText\"></div>\r\n    </div>\r\n\r\n    <div class=\"footer-bar\">\r\n      <div data-i18n=\"reports.footerBrand\"></div>\r\n      <div data-i18n=\"reports.footerRef\"></div>\r\n      <div data-i18n=\"reports.footerPage\"></div>\r\n    </div>\r\n  </div>\r\n</body>\r\n</html>";
